# Let's automate this process for all the songs in todo_songs: search for each song, get the first matching result, and extract the release month/year.
release_info = []
for song in todo_songs:
    query = f"{song['title']} {' '.join(song['artists'])}"
    results = apis.spotify.search_songs(query=query, page_limit=3)
    # Find the first result that matches both title and at least one artist
    found = None
    for res in results:
        if res["title"].lower() == song["title"].lower() and any(
            a["name"].lower() in [artist.lower() for artist in song["artists"]] for a in res["artists"]
        ):
            found = res
            break
    if found:
        release_date = found["release_date"]
        release_month = datetime.strptime(release_date, "%Y-%m-%dT%H:%M:%S").strftime("%m/%Y")
    else:
        release_month = "UNKNOWN"
    release_info.append({
        "title": song["title"],
        "artists": song["artists"],
        "release_month": release_month
    })
print(release_info)

